#!/bin/sh
# Print the three IP addresses that appear most often in access.log,
# one per line, most frequent first. Ties are broken by first appearance
# in the log. Assumes the client IP is the first whitespace-delimited field.
set -eu

log="$(dirname "$0")/access.log"
[ -f access.log ] && log="access.log"

awk '
{
    ip = $1
    if (!(ip in seen)) {
        seen[ip] = ++order     # remember first-appearance order
    }
    count[ip]++
}
END {
    n = 0
    for (ip in count) {
        n++
        ids[n] = ip
    }
    # selection sort: higher count first, earlier first-appearance first
    for (i = 1; i <= n && i <= 3; i++) {
        best = i
        for (j = i + 1; j <= n; j++) {
            a = ids[best]; b = ids[j]
            if (count[b] > count[a] ||
                (count[b] == count[a] && order[b] < order[a]))
                best = j
        }
        tmp = ids[i]; ids[i] = ids[best]; ids[best] = tmp
        print ids[i]
    }
}
' "$log"
